import{_ as t,o as n,c as i,a2 as r}from"./chunks/framework.7R1OEGYz.js";const s="/docs/images/manual/dashboard.png",p=JSON.parse('{"title":"4. Dashboard","description":"Ringkasan kondisi pembangkit hari ini.","frontmatter":{"title":"4. Dashboard","description":"Ringkasan kondisi pembangkit hari ini."},"headers":[],"relativePath":"dashboard.md","filePath":"dashboard.md"}'),e={name:"dashboard.md"};function d(o,a,u,g,l,h){return n(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="_4-dashboard" tabindex="-1">4. Dashboard <a class="header-anchor" href="#_4-dashboard" aria-label="Permalink to &quot;4. Dashboard&quot;">​</a></h1><p>Ringkasan kondisi pembangkit hari ini. <span class="manual-badge is-public">Akses: Semua Pengguna</span></p><p>Dashboard adalah halaman pertama setelah login. Isinya diperbarui otomatis dari data yang diinput di setiap modul.</p><figure class="manual-figure"><p><img src="'+s+'" alt="Dashboard: peringatan BBM, ringkasan KPI, kelengkapan input, dan gangguan terbaru."></p><figcaption>Dashboard: peringatan BBM, ringkasan KPI, kelengkapan input, dan gangguan terbaru.</figcaption></figure><h2 id="bagian-bagian-dashboard" tabindex="-1">Bagian-bagian Dashboard <a class="header-anchor" href="#bagian-bagian-dashboard" aria-label="Permalink to &quot;Bagian-bagian Dashboard&quot;">​</a></h2><ul><li><strong>Peringatan BBM</strong>: muncul hanya bila ketahanan stok BBM waspada (≤ 10 hari) atau kritis (≤ 5 hari).</li><li><strong>Ringkasan (KPI)</strong>: beban arus terakhir, kWh produksi hari ini dan bulan ini, jumlah gangguan bulan ini, serta ketahanan stok BBM. Tekan kotak KPI untuk membuka modulnya.</li><li><strong>Kelengkapan input</strong>: daftar data yang harus diisi pada shift berjalan, beserta progresnya. Tekan <strong>Isi</strong> / <strong>Lanjutkan</strong> untuk langsung ke halaman input.</li><li><strong>Gangguan terbaru</strong>: catatan gangguan paling baru dan status penanganannya.</li><li><strong>Grafik</strong>: beban arus hari ini per interval dan produksi kWh 7 hari terakhir.</li><li><strong>Beban per penyulang</strong>: nilai arus terakhir hari ini untuk setiap penyulang. Titik hijau berarti sudah ada data, abu-abu berarti belum.</li></ul><h2 id="arti-warna-status" tabindex="-1">Arti warna status <a class="header-anchor" href="#arti-warna-status" aria-label="Permalink to &quot;Arti warna status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Warna</th><th>Status</th><th>Arti</th></tr></thead><tbody><tr><td>Hijau</td><td>Normal</td><td>Kondisi aman / data lengkap.</td></tr><tr><td>Kuning</td><td>Waspada</td><td>Perlu perhatian, mis. stok BBM ≤ 10 hari atau gangguan belum selesai.</td></tr><tr><td>Merah</td><td>Kritis</td><td>Perlu tindakan segera, mis. stok BBM ≤ 5 hari.</td></tr><tr><td>Abu-abu</td><td>Belum ada data</td><td>Data belum diinput.</td></tr></tbody></table>',8)])])}const k=t(e,[["render",d]]);export{p as __pageData,k as default};
